        "content": "import { describe, expect, test } from \"bun:test\";\nimport { validateJson } from \"./validate-json\";\n\ndescribe(\"validateJson\", () => {\n  test(\"valid simple object\", () => {\n    const result = validateJson('{\"key\": \"value\"}');\n    expect(result.valid).toBe(true);\n    expect(result.error).toBeUndefined();\n  });\n\n  test(\"valid array\", () => {\n    const result = validateJson('[1, 2, 3]');\n    expect(result.valid).toBe(true);\n  });\n\n  test(\"valid nested object\", () => {\n    const result = validateJson('{\"a\": {\"b\": {\"c\": 1}}}');\n    expect(result.valid).toBe(true);\n  });\n\n  test(\"valid string primitive\", () => {\n    const result = validateJson('\"hello\"');\n    expect(result.valid).toBe(true);\n  });\n\n  test(\"valid number primitive\", () => {\n    const result = validateJson(\"42\");\n    expect(result.valid).toBe(true);\n  });\n\n  test(\"valid unicode content\", () => {\n    const result = validateJson('{\"emoji\": \"\\u2603\", \"jp\": \"\\u3053\\u3093\\u306b\\u3061\\u306f\"}');\n    expect(result.valid).toBe(true);\n  });\n\n  test(\"invalid JSON returns error\", () => {\n    const result = validateJson(\"{not valid json}\");\n    expect(result.valid).toBe(false);\n    expect(result.error).toBeDefined();\n  });\n\n  test(\"empty string returns error\", () => {\n    const result = validateJson(\"\");\n    expect(result.valid).toBe(false);\n    expect(result.error).toBe(\"Empty input\");\n  });\n\n  test(\"whitespace-only string returns error\", () => {\n    const result = validateJson(\"   \\n\\t  \");\n    expect(result.valid).toBe(false);\n    expect(result.error).toBe(\"Empty input\");\n  });\n\n  test(\"trailing comma is invalid\", () => {\n    const result = validateJson('{\"a\": 1,}');\n    expect(result.valid).toBe(false);\n    expect(result.error).toBeDefined();\n  });\n});\n"
