/**
 * JSON validator utility. Validates JSON input from stdin.
 */

export type ValidationResult = {
  valid: boolean;
  error?: string;
};

/**
 * Validate a string as JSON. Returns a result indicating success or failure.
 */
export function validateJson(input: string): ValidationResult {
  if (input.trim() === "") {
    return { valid: false, error: "Empty input" };
  }

  try {
    JSON.parse(input);
    return { valid: true };
  } catch (e) {
    const message = e instanceof Error ? e.message : "Unknown parse error";
    return { valid: false, error: message };
  }
}

async function main(): Promise<void> {
  const text = await new Response(Bun.stdin.stream()).text();
  const result = validateJson(text);

  if (result.valid) {
    console.log("Valid JSON");
    process.exit(0);
  } else {
    console.error(`Invalid JSON: ${result.error}`);
    process.exit(1);
  }
}

main();

import { describe, expect, test } from "bun:test";
import { validateJson } from "./validate-json";

describe("validateJson", () => {
  test("valid simple object", () => {
    const result = validateJson('{"key": "value"}');
    expect(result.valid).toBe(true);
    expect(result.error).toBeUndefined();
  });

  test("valid array", () => {
    const result = validateJson('[1, 2, 3]');
    expect(result.valid).toBe(true);
  });

  test("valid nested object", () => {
    const result = validateJson('{"a": {"b": {"c": 1}}}');
    expect(result.valid).toBe(true);
  });

  test("valid string primitive", () => {
    const result = validateJson('"hello"');
    expect(result.valid).toBe(true);
  });

  test("valid number primitive", () => {
    const result = validateJson("42");
    expect(result.valid).toBe(true);
  });

  test("valid unicode content", () => {
    const result = validateJson('{"emoji": "\u2603", "jp": "\u3053\u3093\u306b\u3061\u306f"}');
    expect(result.valid).toBe(true);
  });

  test("invalid JSON returns error", () => {
    const result = validateJson("{not valid json}");
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
  });

  test("empty string returns error", () => {
    const result = validateJson("");
    expect(result.valid).toBe(false);
    expect(result.error).toBe("Empty input");
  });

  test("whitespace-only string returns error", () => {
    const result = validateJson("   \n\t  ");
    expect(result.valid).toBe(false);
    expect(result.error).toBe("Empty input");
  });

  test("trailing comma is invalid", () => {
    const result = validateJson('{"a": 1,}');
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
  });
});

