        "new_string": "/**\n * Generate a personalized greeting based on the time of day.\n */\nexport function personalGreet(name: string, timeOfDay: string): string {\n  const normalized = timeOfDay.trim().toLowerCase();\n  let period: string;\n\n  switch (normalized) {\n    case \"morning\":\n      period = \"morning\";\n      break;\n    case \"afternoon\":\n      period = \"afternoon\";\n      break;\n    case \"evening\":\n      period = \"evening\";\n      break;\n    default:\n      period = \"day\";\n      break;\n  }\n\n  return `Good ${period}, ${name}!`;\n}\n\n/**\n * Add two numbers.\n */\nexport function add(a: number, b: number): number {\n  return a + b;\n}"
