import { describe, expect, test } from "bun:test";
import { greet, add, personalGreet } from "./utils";

describe("utils", () => {
  test("greet returns greeting message", () => {
    expect(greet("Alice")).toBe("Hello, Alice!");
  });

  test("add returns sum of two numbers", () => {
    expect(add(2, 3)).toBe(5);
  });
});

describe("personalGreet", () => {
  test("returns morning greeting", () => {
    expect(personalGreet("Alice", "morning")).toBe("Good morning, Alice!");
  });

  test("returns afternoon greeting", () => {
    expect(personalGreet("Bob", "afternoon")).toBe("Good afternoon, Bob!");
  });

  test("returns evening greeting", () => {
    expect(personalGreet("Charlie", "evening")).toBe("Good evening, Charlie!");
  });

  test("falls back to 'day' for unrecognized time of day", () => {
    expect(personalGreet("Dana", "midnight")).toBe("Good day, Dana!");
  });

  test("handles whitespace and case variations", () => {
    expect(personalGreet("Eve", "  Morning  ")).toBe("Good morning, Eve!");
    expect(personalGreet("Eve", "AFTERNOON")).toBe("Good afternoon, Eve!");
  });
});

