        "content": "import { describe, expect, test } from \"bun:test\";\nimport { validateJsonString, validateJsonFile } from \"./json-validator\";\nimport { join } from \"path\";\nimport { tmpdir } from \"os\";\n\ndescribe(\"validateJsonString\", () => {\n  describe(\"valid JSON\", () => {\n    test(\"simple object\", () => {\n      expect(validateJsonString('{\"key\": \"value\"}')).toEqual({ valid: true });\n    });\n\n    test(\"simple array\", () => {\n      expect(validateJsonString('[1, 2, 3]')).toEqual({ valid: true });\n    });\n\n    test(\"nested object\", () => {\n      const json = '{\"a\": {\"b\": {\"c\": [1, 2, {\"d\": true}]}}}';\n      expect(validateJsonString(json)).toEqual({ valid: true });\n    });\n\n    test(\"nested array\", () => {\n      const json = '[[1, [2, [3]]]]';\n      expect(validateJsonString(json)).toEqual({ valid: true });\n    });\n\n    test(\"string value\", () => {\n      expect(validateJsonString('\"hello\"')).toEqual({ valid: true });\n    });\n\n    test(\"number values\", () => {\n      expect(validateJsonString(\"42\")).toEqual({ valid: true });\n      expect(validateJsonString(\"-1\")).toEqual({ valid: true });\n      expect(validateJsonString(\"3.14\")).toEqual({ valid: true });\n      expect(validateJsonString(\"1e10\")).toEqual({ valid: true });\n      expect(validateJsonString(\"1E10\")).toEqual({ valid: true });\n      expect(validateJsonString(\"1.5e-3\")).toEqual({ valid: true });\n      expect(validateJsonString(\"0\")).toEqual({ valid: true });\n      expect(validateJsonString(\"-0.5\")).toEqual({ valid: true });\n      expect(validateJsonString(\"1e+10\")).toEqual({ valid: true });\n    });\n\n    test(\"boolean values\", () => {\n      expect(validateJsonString(\"true\")).toEqual({ valid: true });\n      expect(validateJsonString(\"false\")).toEqual({ valid: true });\n    });\n\n    test(\"null value\", () => {\n      expect(validateJsonString(\"null\")).toEqual({ valid: true });\n    });\n\n    test(\"empty object\", () => {\n      expect(validateJsonString(\"{}\")).toEqual({ valid: true });\n    });\n\n    test(\"empty array\", () => {\n      expect(validateJsonString(\"[]\")).toEqual({ valid: true });\n    });\n\n    test(\"unicode escape sequences\", () => {\n      expect(validateJsonString('\"\\\\u0048\\\\u0065\\\\u006C\\\\u006Co\"')).toEqual({\n        valid: true,\n      });\n    });\n\n    test(\"string escape sequences\", () => {\n      expect(validateJsonString('\"line1\\\\nline2\\\\ttab\\\\\\\\\"')).toEqual({\n        valid: true,\n      });\n      expect(validateJsonString('\"quote\\\\\"inside\"')).toEqual({ valid: true });\n      expect(validateJsonString('\"slash\\\\/\"')).toEqual({ valid: true });\n      expect(validateJsonString('\"back\\\\b front\\\\f\"')).toEqual({ valid: true });\n      expect(validateJsonString('\"return\\\\r\"')).toEqual({ valid: true });\n    });\n\n    test(\"whitespace handling\", () => {\n      expect(validateJsonString('  { \"a\" : 1 }  ')).toEqual({ valid: true });\n      expect(validateJsonString('\\n\\t{\"a\":\\r\\n1}\\n')).toEqual({ valid: true });\n    });\n\n    test(\"mixed types in array\", () => {\n      const json = '[1, \"two\", true, null, {\"five\": 5}, [6]]';\n      expect(validateJsonString(json)).toEqual({ valid: true });\n    });\n\n    test(\"complex real-world JSON\", () => {\n      const json = JSON.stringify({\n        users: [\n          { id: 1, name: \"Alice\", active: true, roles: [\"admin\", \"user\"] },\n          { id: 2, name: \"Bob\", active: false, roles: [], metadata: null },\n        ],\n        total: 2,\n        page: { current: 1, size: 10 },\n      });\n      expect(validateJsonString(json)).toEqual({ valid: true });\n    });\n  });\n\n  describe(\"invalid JSON\", () => {\n    test(\"trailing comma in object\", () => {\n      const result = validateJsonString('{\"a\": 1,}');\n      expect(result.valid).toBe(false);\n    });\n\n    test(\"trailing comma in array\", () => {\n      const result = validateJsonString(\"[1, 2,]\");\n      expect(result.valid).toBe(false);\n    });\n\n    test(\"single quotes\", () => {\n      const result = validateJsonString(\"{'key': 'value'}\");\n      expect(result.valid).toBe(false);\n    });\n\n    test(\"unterminated string\", () => {\n      const result = validateJsonString('\"hello');\n      expect(result.valid).toBe(false);\n    });\n\n    test(\"unquoted keys\", () => {\n      const result = validateJsonString(\"{key: 1}\");\n      expect(result.valid).toBe(false);\n    });\n\n    test(\"bare value identifier\", () => {\n      const result = validateJsonString(\"undefined\");\n      expect(result.valid).toBe(false);\n    });\n\n    test(\"leading zeros\", () => {\n      const result = validateJsonString(\"01\");\n      expect(result.valid).toBe(false);\n    });\n\n    test(\"missing value after colon\", () => {\n      const result = validateJsonString('{\"a\":}');\n      expect(result.valid).toBe(false);\n    });\n\n    test(\"missing comma between elements\", () => {\n      const result = validateJsonString(\"[1 2]\");\n      expect(result.valid).toBe(false);\n    });\n\n    test(\"extra closing bracket\", () => {\n      const result = validateJsonString(\"[1]]\");\n      expect(result.valid).toBe(false);\n    });\n\n    test(\"mismatched brackets\", () => {\n      const result = validateJsonString(\"[1}\");\n      expect(result.valid).toBe(false);\n    });\n\n    test(\"incomplete keyword\", () => {\n      const result = validateJsonString(\"tru\");\n      expect(result.valid).toBe(false);\n    });\n\n    test(\"invalid escape sequence\", () => {\n      const result = validateJsonString('\"bad\\\\x\"');\n      expect(result.valid).toBe(false);\n    });\n\n    test(\"invalid unicode escape\", () => {\n      const result = validateJsonString('\"bad\\\\u00GG\"');\n      expect(result.valid).toBe(false);\n    });\n\n    test(\"control character in string\", () => {\n      const result = validateJsonString('\"has\\nnewline\"');\n      expect(result.valid).toBe(false);\n    });\n\n    test(\"multiple top-level values\", () => {\n      const result = validateJsonString(\"1 2\");\n      expect(result.valid).toBe(false);\n    });\n\n    test(\"number with trailing dot\", () => {\n      const result = validateJsonString(\"1.\");\n      expect(result.valid).toBe(false);\n    });\n\n    test(\"number with trailing e\", () => {\n      const result = validateJsonString(\"1e\");\n      expect(result.valid).toBe(false);\n    });\n\n    test(\"just a minus sign\", () => {\n      const result = validateJsonString(\"-\");\n      expect(result.valid).toBe(false);\n    });\n  });\n\n  describe(\"edge cases\", () => {\n    test(\"empty input\", () => {\n      const result = validateJsonString(\"\");\n      expect(result.valid).toBe(false);\n      expect(result.error).toBe(\"Empty input\");\n    });\n\n    test(\"whitespace only\", () => {\n      const result = validateJsonString(\"   \\n\\t\\r  \");\n      expect(result.valid).toBe(false);\n    });\n\n    test(\"deeply nested structure\", () => {\n      const depth = 100;\n      const json = \"[\".repeat(depth) + \"1\" + \"]\".repeat(depth);\n      expect(validateJsonString(json)).toEqual({ valid: true });\n    });\n\n    test(\"large payload\", () => {\n      const items = Array.from({ length: 1000 }, (_, i) => `{\"id\":${i},\"name\":\"item${i}\",\"value\":${i * 1.5}}`);\n      const json = \"[\" + items.join(\",\") + \"]\";\n      expect(validateJsonString(json)).toEqual({ valid: true });\n    });\n\n    test(\"string with all escape types\", () => {\n      const json = '\"\\\\\" \\\\\\\\ \\\\/ \\\\b \\\\f \\\\n \\\\r \\\\t \\\\u0041\"';\n      expect(validateJsonString(json)).toEqual({ valid: true });\n    });\n\n    test(\"unicode in key\", () => {\n      expect(validateJsonString('{\"\\\\u0041\": 1}')).toEqual({ valid: true });\n    });\n\n    test(\"error position is reported\", () => {\n      const result = validateJsonString('{\"a\": }');\n      expect(result.valid).toBe(false);\n      expect(typeof result.position).toBe(\"number\");\n    });\n  });\n});\n\ndescribe(\"validateJsonFile\", () => {\n  test(\"validates a valid JSON file\", async () => {\n    const filePath = join(tmpdir(), `test-valid-${Date.now()}.json`);\n    await Bun.write(filePath, '{\"valid\": true}');\n    const result = await validateJsonFile(filePath);\n    expect(result).toEqual({ valid: true });\n  });\n\n  test(\"reports error for invalid JSON file\", async () => {\n    const filePath = join(tmpdir(), `test-invalid-${Date.now()}.json`);\n    await Bun.write(filePath, \"{bad}\");\n    const result = await validateJsonFile(filePath);\n    expect(result.valid).toBe(false);\n  });\n\n  test(\"reports error for missing file\", async () => {\n    const result = await validateJsonFile(\"/tmp/nonexistent-file-abc123.json\");\n    expect(result.valid).toBe(false);\n    expect(result.error).toContain(\"File not found\");\n  });\n});\n\ndescribe(\"performance\", () => {\n  test(\"validates typical payload in sub-millisecond time\", () => {\n    const payload = JSON.stringify({\n      users: Array.from({ length: 100 }, (_, i) => ({\n        id: i,\n        name: `User ${i}`,\n        email: `user${i}@example.com`,\n        active: i % 2 === 0,\n        scores: [i * 10, i * 20, i * 30],\n        metadata: { created: \"2026-01-01\", tags: [\"a\", \"b\"] },\n      })),\n    });\n\n    // Warmup\n    for (let w = 0; w < 10; w++) {\n      validateJsonString(payload);\n    }\n\n    const iterations = 100;\n    const start = performance.now();\n    for (let j = 0; j < iterations; j++) {\n      validateJsonString(payload);\n    }\n    const elapsed = performance.now() - start;\n    const avgMs = elapsed / iterations;\n\n    expect(validateJsonString(payload)).toEqual({ valid: true });\n    expect(avgMs).toBeLessThan(1);\n  });\n\n  test(\"validates large payload efficiently\", () => {\n    const items = Array.from({ length: 10000 }, (_, i) =>\n      `{\"id\":${i},\"value\":\"${\"x\".repeat(50)}\"}`\n    );\n    const json = \"[\" + items.join(\",\") + \"]\";\n\n    const start = performance.now();\n    const result = validateJsonString(json);\n    const elapsed = performance.now() - start;\n\n    expect(result).toEqual({ valid: true });\n    expect(elapsed).toBeLessThan(100);\n  });\n});\n"
