}\n        if (cc === 0x7b) { // {\n          stack.push(Container.OBJECT);\n          state = State.EXPECT_KEY;\n          i++;\n          continue;\n        }\n        if (cc === 0x5b) { // [\n          stack.push(Container.ARRAY);\n          state = State.EXPECT_VALUE;\n          i++;\n          continue;\n        }\n        if (cc === 0x5d && stack.length > 0 && stack[stack.length - 1] === Container.ARRAY) { // ] empty array\n          stack.pop();\n          state = State.AFTER_VALUE;\n          hasValueAtRoot = stack.length === 0;\n          i++;\n          continue;\n        }\n        if (cc === 0x2d || DIGIT.has(cc)) { // - or digit\n          numberHasDot = false;\n          numberHasExp = false;\n          numberNeedsDigit = false;\n          numberStartedWithZero = false;\n          if (cc === 0x2d) {\n            numberNeedsDigit = true;\n          } else if (cc === 0x30) {\n            numberStartedWithZero = true;\n          }\n          state = State.IN_NUMBER;\n          i++;\n          continue;\n        }\n        const ch = input[i];\n        if (ch === \"t\" || ch === \"f\" || ch === \"n\") {\n          keywordExpected = KEYWORDS[ch];\n          keyword = ch;\n          keywordStart = i;\n          state = State.IN_KEYWORD;\n          i++;\n          continue;\n        }\n        return err(`Unexpected character '${input[i]}'`, i);\n      }\n\n      case State.IN_STRING: {\n        if (cc === 0x5c) { // backslash\n          state = State.IN_STRING_ESCAPE;\n          i++;\n          continue;\n        }\n        if (cc === 0x22) { // \"\n          state = State.AFTER_VALUE;\n          hasValueAtRoot = stack.length === 0;\n          i++;\n          continue;\n        }\n        if (cc < 0x20) {\n          return err(\"Unescaped control character in string\", i);\n        }\n        i++;\n        continue;\n      }\n\n      case State.IN_STRING_ESCAPE: {\n        if (\n          cc === 0x22 || // \"\n          cc === 0x5c || // \\\n          cc === 0x2f || // /\n          cc === 0x62 || // b\n          cc === 0x66 || // f\n          cc === 0x6e || // n\n          cc === 0x72 || // r\n          cc === 0x74    // t\n        ) {\n          state = State.IN_STRING;\n          i++;\n          continue;\n        }\n        if (cc === 0x75) { // u\n          unicodeCount = 0;\n          state = State.IN_STRING_UNICODE;\n          i++;\n          continue;\n        }\n        return err(`Invalid escape sequence '\\\\${input[i]}'`, i - 1);\n      }\n\n      case State.IN_STRING_UNICODE: {\n        if (HEX.has(cc)) {\n          unicodeCount++;\n          if (unicodeCount === 4) {\n            state = State.IN_STRING;\n          }\n          i++;\n          continue;\n        }\n        return err(\"Invalid unicode escape sequence\", i);\n      }\n\n      case State.IN_NUMBER: {\n        if (DIGIT.has(cc)) {\n          if (numberStartedWithZero && !numberHasDot && !numberHasExp && !numberNeedsDigit) {\n            return err(\"Leading zeros not allowed\", i);\n          }\n          numberNeedsDigit = false;\n          numberStartedWithZero = false;\n          i++;\n          continue;\n        }\n        if (cc === 0x2e) { // .\n          if (numberHasDot || numberHasExp || numberNeedsDigit) {\n            return err(\"Invalid number format\", i);\n          }\n          numberHasDot = true;\n          numberNeedsDigit = true;\n          numberStartedWithZero = false;\n          i++;\n          continue;\n        }\n        if (cc === 0x65 || cc === 0x45) { // e E\n          if (numberHasExp || numberNeedsDigit) {\n            return err(\"Invalid number format\", i);\n          }\n          numberHasExp = true;\n          numberNeedsDigit = true;\n          numberStartedWithZero = false;\n          i++;\n          if (i < len) {\n            const next = input.charCodeAt(i);\n            if (next === 0x2b || next === 0x2d) { // + -\n              i++;\n            }\n          }\n          continue;\n        }\n        if (numberNeedsDigit) {\n          return err(\"Invalid number format\", i);\n        }\n        // Number complete -- do not advance i, re-process in AFTER_VALUE\n        state = State.AFTER_VALUE;\n        hasValueAtRoot = stack.length === 0;\n        continue;\n      }\n\n      case State.IN_KEYWORD: {\n        keyword += input[i];\n        if (keyword.length === keywordExpected.length) {\n          if (keyword !== keywordExpected) {\n            return err(`Invalid keyword '${keyword}'`, keywordStart);\n          }\n          state = State.AFTER_VALUE;\n          hasValueAtRoot = stack.length === 0;\n          i++;\n          continue;\n        }\n        if (!keywordExpected.startsWith(keyword)) {\n          return err(`Invalid keyword '${keyword}'`, keywordStart);\n        }\n        i++;\n        continue;\n      }\n\n      case State.AFTER_VALUE: {\n        if (WHITESPACE.has(cc)) {\n          i++;\n          continue;\n        }\n        if (stack.length === 0) {\n          // Should be end of input; any non-whitespace here is an error\n          return err(`Unexpected character '${input[i]}' after top-level value`, i);\n        }\n        const container = stack[stack.length - 1];\n        if (cc === 0x2c) { // ,\n          if (container === Container.OBJECT) {\n            state = State.EXPECT_KEY;\n          } else {\n            state = State.EXPECT_VALUE;\n          }\n          i++;\n          continue;\n        }\n        if (cc === 0x7d && container === Container.OBJECT) { // }\n          stack.pop();\n          hasValueAtRoot = stack.length === 0;\n          i++;\n          continue;\n        }\n        if (cc === 0x5d && container === Container.ARRAY) { // ]\n          stack.pop();\n          hasValueAtRoot = stack.length === 0;\n          i++;\n          continue;\n        }\n        return err(`Unexpected character '${input[i]}'`, i);\n      }\n\n      case State.EXPECT_KEY: {\n        if (WHITESPACE.has(cc)) {\n          i++;\n          continue;\n        }\n        if (cc === 0x7d && stack.length > 0 && stack[stack.length - 1] === Container.OBJECT) { // } empty object\n          stack.pop();\n          state = State.AFTER_VALUE;\n          hasValueAtRoot = stack.length === 0;\n          i++;\n          continue;\n        }\n        if (cc === 0x22) { // \"\n          state = State.AFTER_KEY;\n          i++;\n          continue;\n        }\n        return err(\"Expected string key\", i);\n      }\n\n      case State.AFTER_KEY: {\n        // Reading key string characters\n        if (cc === 0x5c) { // backslash\n          state = State.IN_STRING_ESCAPE;\n          // After escape, need to return to AFTER_KEY not IN_STRING\n          // We use a trick: store that we're in a key string via EXPECT_COLON transition\n          // Actually let's handle key strings inline\n          i++;\n          // Process escape\n          if (i >= len) return err(\"Unexpected end of input in string escape\", i);\n          const esc = input.charCodeAt(i);\n          if (\n            esc === 0x22 || esc === 0x5c || esc === 0x2f ||\n            esc === 0x62 || esc === 0x66 || esc === 0x6e ||\n            esc === 0x72 || esc === 0x74\n          ) {\n            i++;\n            continue;\n          }\n          if (esc === 0x75) {\n            i++;\n            for (let u = 0; u < 4; u++) {\n              if (i >= len) return err(\"Unexpected end of unicode escape\", i);\n              if (!HEX.has(input.charCodeAt(i))) return err(\"Invalid unicode escape sequence\", i);\n              i++;\n            }\n            continue;\n          }\n          return err(`Invalid escape sequence '\\\\${input[i]}'`, i - 1);\n        }\n        if (cc === 0x22) { // \" end of key\n          state = State.EXPECT_COLON;\n          i++;\n          continue;\n        }\n        if (cc < 0x20) {\n          return err(\"Unescaped control character in string\", i);\n        }\n        i++;\n        continue;\n      }\n\n      case State.EXPECT_COLON: {\n        if (WHITESPACE.has(cc)) {\n          i++;\n          continue;\n        }\n        if (cc === 0x3a) { // :\n          state = State.EXPECT_VALUE;\n          i++;\n          continue;\n        }\n        return err(\"Expected ':' after object key\", i);\n      }\n    }\n  }\n\n  // End of input\n  if (state === State.IN_NUMBER && !numberNeedsDigit) {\n    hasValueAtRoot = stack.length === 0;\n    state = State.AFTER_VALUE;\n  }\n\n  if (state === State.IN_KEYWORD) {\n    if (keyword === keywordExpected) {\n      hasValueAtRoot = stack.length === 0;\n      state = State.AFTER_VALUE;\n    } else {\n      return err(`Unexpected end of input in keyword '${keyword}'`, keywordStart);\n    }\n  }\n\n  if (stack.length > 0) {\n    return err(\"Unexpected end of input: unclosed structure\", i);\n  }\n\n  if (!hasValueAtRoot && state !== State.AFTER_VALUE) {\n    return err(\"No valid JSON value found\", 0);\n  }\n\n  if (state !== State.AFTER_VALUE) {\n    return err(\"Unexpected end of input\", i);\n  }\n\n  return { valid: true };\n}\n\n/**\n * Validate a JSON file using Bun.file for efficient file reading.\n */\nexport async function validateJsonFile(filePath: string): Promise<ValidationResult> {\n  try {\n    const file = Bun.file(filePath);\n    const exists = await file.exists();\n    if (!exists) {\n      return { valid: false, error: `File not found: ${filePath}`, position: 0 };\n    }\n    const content = await file.text();\n    return validateJsonString(content);\n  } catch (e) {\n    const message = e instanceof Error ? e.message : String(e);\n    return { valid: false, error: `Failed to read file: ${message}`, position: 0 };\n  }\n}\n"
