        "content": "/**\n * CLI entry point for JSON validation.\n * Usage: bun run validate <file-path>\n * Or pipe via stdin: echo '{\"a\":1}' | bun run validate\n */\n\nimport { validateJsonString, validateJsonFile } from \"./json-validator\";\n\nasync function main(): Promise<void> {\n  const filePath = process.argv[2];\n\n  if (filePath) {\n    const result = await validateJsonFile(filePath);\n    if (result.valid) {\n      console.log(\"Valid JSON\");\n      process.exit(0);\n    } else {\n      console.error(`Invalid JSON: ${result.error} (position: ${result.position})`);\n      process.exit(1);\n    }\n    return;\n  }\n\n  // Read from stdin\n  const chunks: Buffer[] = [];\n  const reader = Bun.stdin.stream().getReader();\n\n  while (true) {\n    const { done, value } = await reader.read();\n    if (done) break;\n    chunks.push(Buffer.from(value));\n  }\n\n  const input = Buffer.concat(chunks).toString(\"utf-8\");\n\n  if (!input.length) {\n    console.error(\"No input provided. Usage: bun run validate <file-path>\");\n    process.exit(1);\n  }\n\n  const result = validateJsonString(input);\n  if (result.valid) {\n    console.log(\"Valid JSON\");\n    process.exit(0);\n  } else {\n    console.error(`Invalid JSON: ${result.error} (position: ${result.position})`);\n    process.exit(1);\n  }\n}\n\nmain();\n"
